+  assert.ok(ball.y + ball.r <= brick.y + 0.001, 'ball pushed out above the brick');
+});
+
+test('applyBounce: side hit flips vx, preserves vy, pushes sideways', () => {
+  // Ball arrived from the left: centred vertically, lightly into the left side.
+  const ball = ballAt(100 - 8 + 3, 110, 300, 40);
+  applyBounce(ball, brick);
+  assert.ok(ball.vx < 0, 'vx should flip left');
+  assert.equal(ball.vy, 40, 'vy left untouched');
+  assert.ok(ball.x + ball.r <= brick.x + 0.001, 'ball pushed out to the left');
+});
+
+// Corner: equal penetrations flip both components.
+test('applyBounce: diagonal corner flips both components', () => {
+  // Ball centred on the brick centre = ox === oy.
+  const ball = ballAt(120, 110, 100, 100);
+  applyBounce(ball, brick);
+  assert.ok(ball.vx < 0 && ball.vy < 0, 'both components flip');
+});
+
+// Tunnelling: the ball steps clear over the brick; the sweep catches it.
+test('brickContact: fast ball jumping over the brick is caught (sweep)', () => {
+  // Ball teleports from above the brick to below it in one step, never
+  // overlapping: only the swept segment crosses the brick.
+  const ball = { ...ballAt(120, 90), py: 10, y: 150, x: 120, vy: 300 };
+  assert.equal(collides(ball, brick), false, 'no direct overlap');
+  assert.equal(brickContact(ball, brick), true, 'sweep detects the crossing');
+});
