 export function step(state, dt) {
   const { ball, paddle } = state;

+  // Remember where the ball started this step so brick collision can sweep
+  // the travelled segment and catch the ball travelling FAST enough to jump
+  // clean over a brick between two frames (tunnelling, see #1).
+  ball.px = ball.x;
+  ball.py = ball.y;
+
   ball.x += ball.vx * dt;
   ball.y += ball.vy * dt;

@@ -206,6 +212,102 @@ export function step(state, dt) {
   return false;
 }

+// Earliest time t in [0,1] at which the segment from (x0,y0) to (x1,y1) first
+// enters `box` (an AABB), or null if it never does. Standard slab method.
+function segmentBoxEntry(x0, y0, x1, y1, box) {
+  const dx = x1 - x0;
+  const dy = y1 - y0;
+  let tmin = 0;
+  let tmax = 1;
+
+  if (dx === 0) {
+    if (x0 < box.x || x0 > box.x + box.w) return null;
+  } else {
+    let t1 = (box.x - x0) / dx;
+    let t2 = (box.x + box.w - x0) / dx;
+    if (t1 > t2) [t1, t2] = [t2, t1];
+    tmin = Math.max(tmin, t1);
+    tmax = Math.min(tmax, t2);
+    if (tmin > tmax) return null;
+  }
+
+  if (dy === 0) {
+    if (y0 < box.y || y0 > box.y + box.h) return null;
+  } else {
+    let t1 = (box.y - y0) / dy;
+    let t2 = (box.y + box.h - y0) / dy;
+    if (t1 > t2) [t1, t2] = [t2, t1];
+    tmin = Math.max(tmin, t1);
+    tmax = Math.min(tmax, t2);
+    if (tmin > tmax) return null;
+  }
+
+  return tmin;
+}
+
+// True if the ball, on its way from its previous position to its current one,
+// made contact with `brick`. Handles a direct overlap AND the tunnelling case
+// (a high-speed ball jumping over a brick between two frames). When it detects
+// a tunnel, it parks the ball at the surface of the brick so the overlap
+// resolution below can run against a consistent position.
+export function brickContact(ball, brick) {
+  // Direct overlap: nothing to sweep, we're already touching.
+  if (collides(ball, brick)) return true;
+
+  // Sweep the segment travelled since the last step against the expanded box
+  // (the brick fattened by the ball radius, the Minkowski sum).
+  const entry = segmentBoxEntry(
+    ball.px ?? ball.x,
+    ball.py ?? ball.y,
+    ball.x,
+    ball.y,
+    {
+      x: brick.x - ball.r,
+      y: brick.y - ball.r,
+      w: brick.w + 2 * ball.r,
+      h: brick.h + 2 * ball.r,
+    },
+  );
+  if (entry === null || entry <= 0 || entry >= 1) return false;
+
+  // Reposition the ball at the point it first touched the expanded box so the
+  // overlap resolution picks the right face and pushes it out correctly.
+  ball.x = ball.px + (ball.x - ball.px) * entry;
+  ball.y = ball.py + (ball.y - ball.py) * entry;
+  return true;
+}
+
+// Resolves the bounce once the ball overlaps `brick` (brickContact() parked it
+// there). The axis with the SMALLER penetration is the face that was hit:
+// flip vy on a top/bottom hit, vx on a side hit, and flip both on a perfectly
+// diagonal corner. The ball is pushed back out so it can't re-overlap.
+export function applyBounce(ball, brick) {
+  const cx = brick.x + brick.w / 2;
+  const cy = brick.y + brick.h / 2;
+  const hx = brick.w / 2 + ball.r; // half-extent of the expanded box, x axis
+  const hy = brick.h / 2 + ball.r; // half-extent of the expanded box, y axis
+  const dx = ball.x - cx;
+  const dy = ball.y - cy;
+  const ox = hx - Math.abs(dx); // penetration through a vertical side
+  const oy = hy - Math.abs(dy); // penetration through a horizontal side
+
+  if (ox < oy) {
+    // Side hit: bounce left/right, push out horizontally.
+    ball.vx = -ball.vx;
+    ball.x = dx >= 0 ? cx + hx : cx - hx;
+  } else if (oy < ox) {
+    // Top/bottom hit: bounce up/down, push out vertically.
+    ball.vy = -ball.vy;
+    ball.y = dy >= 0 ? cy + hy : cy - hy;
+  } else {
+    // Perfectly diagonal corner: flip both components.
+    ball.vx = -ball.vx;
+    ball.vy = -ball.vy;
+    ball.x = dx >= 0 ? cx + hx : cx - hx;
+    ball.y = dy >= 0 ? cy + hy : cy - hy;
+  }
+}
